@dataclass
class AlbumPm:
    data: Album
    classical: bool = False
    _subs: list = field(default_factory=list, repr=False)

    @property
    def composer_enabled(self) -> bool:      # decision
        return self.classical

    def apply(self) -> None:                 # command
        self.data.save()
        for notify in list(self._subs):
            notify()
